    public void printReport()
    {
        if (reportContract.parmRdpName() == "@MET:METBankPaymAdviceVendDP") //DP Class of Report and add name Here
        {
            METBankPaymAdviceContract bankPaymAdviceContract = reportContract.parmRdpContract() as METBankPaymAdviceContract;

            printSettings.reportTitle("@MET:PaymentAdvice");
            printSettings.voucherRecId(bankPaymAdviceContract.parmLedgerJournalTransRecId());
        }

        next printReport();
    }
